/* Crextio – application shell
 * Navigation state shared by the sidebar, top navigation, mobile drawer and
 * page search. The shell markup is generated by scripts/build-shell.cjs.
 */
document.addEventListener("alpine:init", () => {
  Alpine.data("appShell", () => ({
    sidebarOpen: window.matchMedia("(min-width: 1024px)").matches,
    shellMobile: false,
    shellSearch: false,
    shellQuery: "",
    shellIndex: 0,
    shellPages: [],
    shellUnread: 4,

    init() {
      // Open the sidebar on desktop and close it on mobile when the breakpoint changes.
      window
        .matchMedia("(min-width: 1024px)")
        .addEventListener("change", (e) => (this.sidebarOpen = e.matches));

      // The search index is read from the sidebar links, so it always matches the menu.
      this.shellPages = [...this.$root.querySelectorAll("[data-nav-link]")].map((a) => ({
        title: a.dataset.title,
        group: a.dataset.group,
        href: a.getAttribute("href"),
        terms: (a.dataset.title + " " + a.dataset.group + " " + a.dataset.keywords).toLowerCase(),
      }));

      try {
        if (localStorage.getItem("crextio-notifications-read")) this.shellUnread = 0;
      } catch (e) {}
      this.$watch("shellUnread", (n) => {
        try {
          if (!n) localStorage.setItem("crextio-notifications-read", "1");
        } catch (e) {}
      });

      window.addEventListener("keydown", (e) => {
        if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") {
          e.preventDefault();
          this.shellOpenSearch();
        }
      });
    },

    get shellResults() {
      const words = this.shellQuery.toLowerCase().split(/\s+/).filter(Boolean);
      return this.shellPages.filter((p) => words.every((w) => p.terms.includes(w)));
    },

    shellOpenSearch() {
      this.shellMobile = false;
      this.shellQuery = "";
      this.shellIndex = 0;
      this.shellSearch = true;
      this.$nextTick(() => this.$refs.shellInput.focus());
    },

    shellMove(step) {
      const n = this.shellResults.length;
      if (n) this.shellIndex = (this.shellIndex + step + n) % n;
    },

    shellGo() {
      const page = this.shellResults[this.shellIndex];
      if (page) window.location.href = page.href;
    },
  }));
});
